    if proc.returncode:
        try:
            err = json.loads(proc.stderr)
            res = {'code':err['Code'], 'error':err}
        except (ValueError, KeyError):
            res = {'code':'CLIError','error':{'message':proc.stderr}}
    else: res = result(proc)
    if filter_key and res['code'] == 'Success':
