    R['role'] = call('create-receiver-role','iam','create-role',{'RoleName':PREFIX,'AssumeRolePolicyDocument':json.dumps(trust)})['Role']['Arn']; save()
    R['log'] = '/aws/lambda/'+PREFIX
    call('create-owned-log','logs','create-log-group',{'logGroupName':R['log']})
    permissions = {'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':'sqs:SendMessage','Resource':R['collector_arn']},{'Effect':'Allow','Action':'sns:ConfirmSubscription','Resource':R['topic']},{'Effect':'Allow','Action':['logs:CreateLogStream','logs:PutLogEvents'],'Resource':'arn:aws:logs:'+REGION+':'+ACCOUNT+':log-group:'+R['log']+':*'}]}
    call('scope-receiver-permissions','iam','put-role-policy',{'RoleName':PREFIX,'PolicyName':'OwnedReceiver','PolicyDocument':json.dumps(permissions)})
    buf=io.BytesIO()
    with zipfile.ZipFile(buf,'w',zipfile.ZIP_DEFLATED) as z: z.writestr('receiver.py',(HERE/'receiver.py').read_text())
    path_id = uuid.uuid4().hex
    fparams={'FunctionName':PREFIX,'Runtime':'python3.12','Role':R['role'],'Handler':'receiver.handler','Timeout':15,'MemorySize':128,'Code':{'ZipFile':base64.b64encode(buf.getvalue()).decode()},'Environment':{'Variables':{'QUEUE_URL':R['collector'],'TOPIC_ARN':R['topic'],'PATH_ID':path_id}}}
    for i in range(12):
        created = call('create-receiver-'+str(i),'lambda','create-function',fparams,strict=False)
        if created.get('FunctionArn'): R['function']=created['FunctionArn']; save(); break
        time.sleep(10)
    assert R.get('function'), 'receiver role did not propagate'
    for i in range(30):
        state=call('receiver-ready-'+str(i),'lambda','get-function-configuration',{'FunctionName':PREFIX})
